function _updateInitiativeOrderOverlay(ph,isApiMode){var ov=document.getElementById('initiativeOrderOverlay');var waitEl=document.getElementById('init-waiting-msg');var diceEl=document.getElementById('init-dice-area');var introSlot=document.getElementById('init-intro-slot');if(!ov)return;if(ph==='init'||ph==='intro'){document.body.classList.add('combat-init-order-active');ov.classList.add('active');ov.setAttribute('aria-hidden','false');if(ph==='intro'){if(waitEl)waitEl.style.display='none';if(diceEl){diceEl.innerHTML='';diceEl.style.display='none';}if(introSlot)introSlot.style.display='';var barIntro=document.getElementById('init-proceed-bar');if(barIntro)barIntro.style.display='none';}else{if(introSlot){introSlot.innerHTML='';introSlot.style.display='none';}if(waitEl)waitEl.style.display=isApiMode?'none':'block';if(diceEl)diceEl.style.display=isApiMode?'':'none';}}else{document.body.classList.remove('combat-init-order-active');ov.classList.remove('active');ov.setAttribute('aria-hidden','true');if(waitEl)waitEl.style.display='none';if(diceEl){diceEl.innerHTML='';diceEl.style.display='';}if(introSlot){introSlot.innerHTML='';introSlot.style.display='none';}var bar2=document.getElementById('init-proceed-bar');if(bar2)bar2.style.display='none';var sk=document.getElementById('initiativeOrderSkip');if(sk){sk.style.display='none';sk.onclick=null;}}}function _mountIntroInitiativeUI(ph,s){var slot=document.getElementById('init-intro-slot');if(!slot)return;if(ph==='intro'){slot.style.display='';var restoreHtml='';if(s&&s.can_restore&&isApiMode){restoreHtml='<div class="action-bar init-restore-bar"><button type="button" class="action-btn primary full-width" data-action="restore" style="font-size:14px;padding:12px">↻ Restaurar Combate</button></div>';}slot.innerHTML='<div id="init-hero-area" class="init-hero-area"><div class="init-dice3d-wrap" id="initDice3dWrap"><div class="init-dice3d-particles" id="initDice3dParticles"></div><div class="init-dice3d-canvas" id="initDice3dCanvas"></div></div>'+'<div class="init-hero-result" id="initHeroResult"></div><button type="button" class="init-hero-btn" id="initHeroBtn" data-action="initiative">ROLAR INICIATIVA</button><div class="init-hero-subtitle">Toque para determinar a ordem de combate</div></div>'+restoreHtml;}else{slot.innerHTML='';slot.style.display='none';}}
function _showProceedBar(){const bar=document.getElementById('init-proceed-bar');if(bar){bar.style.display='';const pb=bar.querySelector('.action-btn');if(pb)pb.classList.remove('disabled');}var sk=document.getElementById('initiativeOrderSkip');if(sk){sk.style.display='none';sk.onclick=null;}}
function _showBattleLog(){var feed=window._resolutionFeed||[];if(!feed.length){console.warn('[COMBAT] no feed data for battle log');return;}var bodyHtml='<div class="battle-log-list">';feed.forEach(function(entry,i){if(!entry)return;var cleaned=entry.replace(/<[^>]*>/g,'').trim();if(!cleaned)return;var isRound=/^[─═━▬]|Rodada\s+\d|ROUND/i.test(cleaned);if(isRound){bodyHtml+='<div class="battle-log-round">'+escHtml(cleaned)+'</div>';}else{bodyHtml+='<div class="battle-log-entry">'+escHtml(cleaned)+'</div>';}});bodyHtml+='</div>';if(typeof vPopup!=='undefined'){vPopup.show({title:'📜 Log de Batalha',body:bodyHtml,actions:[{label:'Fechar',primary:true,action:function(){vPopup.hide();}}]});}}
var _DMG_FLASH_TYPES=new Set(['fire','cold','lightning','necrotic','radiant','poison','acid','psychic','thunder']);var _origShowError=window.showError;window.showError=function(msg,err){_actionSent=false;_timerExpiredPending=false;document.querySelectorAll('#app .action-btn').forEach(b=>b.classList.remove('disabled'));if(_origShowError)_origShowError(msg,err);};